TP.register({id:"lp5-g2",lp:5,grade:"2",mode:"curriculum",checks:4,nextGrade:"3rd grade",build(E){const F=E.F;const TRAIL="Mira woke up in a tent at base camp. Base camp is where the team sleeps and keeps its food. The air was so cold. Her breath made little clouds. Her job today was to mark the trail. She packed twelve red flags on a small sled. She pulled it up the long ridge. Every fifty steps she pushed a flag into the snow. Red shows up well on white snow. So the team could find the way back. Near the top, the wind took her last flag. Mira tied her scarf to a ski pole. She stood it up instead.";const FLOE="The sea near the poles gets very cold. The top of the water freezes. The ice cracks into flat pieces that float. A flat piece of floating sea ice is called an ice floe. Some floes are smaller than a bed. Others are as wide as a soccer field. Seals climb onto floes to rest. Scientists test a floe with a long pole before they step on it. A thin floe can tip. So the team walks only on thick ice.";const LIGHTS="On some clear winter nights, waves of green and pink light move across the sky near the North Pole. People call this the northern lights. The lights come from tiny bits of energy from the sun. The bits crash into the air high above the earth and make it glow. The glow can look like a curtain blowing in the wind. The lights are too far up to make any sound. The same thing happens near the South Pole, and there people call it the southern lights.";const WORDS=["froze","chest","north","tail","crowd","flew","campsite","unpack","windy","thought","drook","flarn"];const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${text}</p>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>{const eye=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`;const blush=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`;const smile=(x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`;return eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4)});const kface=(x,y,k,sp,mw)=>`<g transform="translate(${x} ${y}) scale(${k})">${K_FACE(0,0,sp,mw||4)}</g>`;const INK="#6B4A3C",RED="#DE5A48";function thermo(v){const top=20,bot=-30,H=220,y=d=>20+(top-d)/(top-bot)*H,yv=y(v);let s=`<svg viewBox="0 0 150 ${H+62}" width="150" role="img" aria-label="Thermometer reading ${Math.abs(v)} below zero">`;s+=`<rect x="54" y="14" width="26" height="${H+14}" rx="13" fill="#FBF6EC" stroke="${INK}" stroke-width="3.4"/>`;s+=`<rect x="60" y="${yv}" width="14" height="${H+36-yv}" rx="7" fill="${RED}"/>`;s+=`<circle cx="67" cy="${H+36}" r="18" fill="${RED}" stroke="${INK}" stroke-width="3.4"/>`;s+=`<ellipse cx="57" cy="${H+28}" rx="4" ry="5.5" fill="#FFFFFF" opacity=".4"/>`;for(let d=top;d>=bot;d-=10){const yy=y(d);s+=`<line x1="80" y1="${yy}" x2="94" y2="${yy}" stroke="${INK}" stroke-width="2.4" stroke-linecap="round"/>`;s+=`<text x="99" y="${yy}" font-size="16" dominant-baseline="central" fill="var(--ink)">${d}</text>`}s+=kface(67,H+32,.52,10,3.4);return s+"</svg>"}const SHOVELS="Nils wanted the path to the weather station cleared before breakfast. He picked up a shovel and started at one end. The snow was soft and deep. By noon he had cleared only half the path. The next morning Ada carried out a second shovel. The two of them started at opposite ends and worked toward each other. They met in the middle. The path was done before the kettle boiled.";const CORE_LOG=F.table(["Day","Ice cores drilled"],[["Monday","6"],["Tuesday","9"],["Wednesday","4"]],{caption:"Ice Cores Drilled"});function shapeSetFig(){const P=(pts,alt)=>F.poly(pts,{size:150,alt});return F.row([P([[50,8],[92,92],[8,92]],"A triangle"),"A"],[P([[22,12],[78,12],[94,88],[6,88]],"A four-sided shape"),"B"],[P([[50,6],[95,40],[78,94],[22,94],[5,40]],"A five-sided shape"),"C"],[P([[28,8],[72,8],[94,50],[72,92],[28,92],[6,50]],"A six-sided shape"),"D"],[F.prism(1,1,1,{unit:76}),"E"])}const LOG=F.table(["Day","Temperature","Wind"],[["Monday","12 below zero","calm"],["Tuesday","9 below zero","strong"],["Wednesday","20 below zero","light"],["Thursday","15 below zero","strong"]],{caption:"Weather Station Log"});const STOPS=[{id:1,title:"Crate Word Flip",short:"Crate Words",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:120,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading words with silent e, vowel teams, r-controlled vowels, two syllables, a prefix, a suffix, and an irregular spelling",key:["Read each word in order. drook and flarn are made-up words: listen for the oo team sound and the ar sound.","Watch for: silent e long o and a short vowel (froze, chest), r-controlled or (north), vowel teams and diphthongs (tail, crowd, flew), a compound word (campsite), a prefix and a suffix (unpack, windy), an irregular spelling (thought)."]}]},{id:2,title:"Load the Sleds",short:"Sled Loads",parts:[{std:["2.OA.A.1"],dur:200,dir:"Read each problem with your teacher. Solve it on your paper. You can draw or write a number sentence. Say your answer.",desc:"one-step addition and subtraction word problems within 100 with the unknown in different places",html:()=>`<p class="big" style="margin-top:0">The team is packing sleds at base camp. A sled is a flat box on runners that the team pulls across the snow.</p>`,qs:["A sled can carry 40 kilograms. The team loads 26 kilograms of food. How many more kilograms can the sled carry?","The team skied 23 kilometers on Monday and 34 kilometers on Tuesday. How many kilometers in all?","Camp A has 28 fuel cans. Camp B has 16 more fuel cans than Camp A. How many fuel cans does Camp B have?","Some crates were sitting on the ice. The team carried 27 of them into the tent. Now 19 crates are left on the ice. How many crates were on the ice at first?","There were 52 flags in the box. The team used 38 of them to mark the trail. How many flags are left?"],key:["14 kilograms (26 + □ = 40, or 40 - 26 = 14)","57 kilometers (23 + 34 = 57)","44 fuel cans (28 + 16 = 44)","46 crates (□ - 27 = 19, or 19 + 27 = 46)","14 flags (52 - 38 = 14)"]}]},{id:3,title:"Camp Journal",short:"Journal",parts:[{title:"Read the Journal Page",std:["RF.2.4"],kind:"read",n:102,label:"words read correctly",dur:110,dir:"Read the story out loud. Use your best reading voice.",desc:"a 102-word grade-level story read aloud",html:()=>`<p class="passage g2-flu">${TRAIL}</p>`,key:["102 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes."]},{title:"Journal Questions",std:["RL.2.1"],dur:85,dir:"Your teacher can read the story again if you need it. Then answer each question out loud.",desc:"asking and answering who, what, why, and how questions about key details in a story",html:()=>`<details class="look-back g2-story" open style="margin-bottom:10px"><summary>Marking the Trail (click to open or close the story)</summary><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${TRAIL}</p></details>`,after:view=>{const d=view.querySelector("details.g2-story");if(d&&view.querySelector(".g2-flu"))d.open=false},qs:["Who pulled the sled up the ridge?","What did she pack on the sled?","Why did the team use red flags on the white snow?","How did she mark the trail after the wind took her last flag?","Your turn. Ask a question about the story. Start with who, what, where, when, why, or how."],key:["Mira","Twelve red flags","Red shows up well on snow, so the team could find the way back.","She tied her scarf to a ski pole and stood the pole up.","Asks a question that is about this story and starts with a question word (for example: Where did Mira sleep? When did the wind take the flag?)."]}]},{id:4,title:"Depth Soundings",short:"Depths",parts:[{std:["2.NBT.B.7"],dur:180,dir:"Solve each one on your paper. Show your work and hold it up. Say your answer.",desc:"adding and subtracting within 1000 with a place value strategy and relating it to a written method",html:()=>`<p class="big" style="margin-top:0">A sounding tells how deep the water is under the ship. The team writes every sounding and every mile in a logbook.</p>`,qs:["The ship sailed 348 kilometers on Monday and 275 kilometers on Tuesday. How far did it sail in all? Show how you added.","The team must travel 500 kilometers to reach the ice shelf. They have gone 236 kilometers. How many kilometers are left?","One sounding was 406 meters deep. The next one was 189 meters deeper than that. How deep was the second sounding?","The ice is 162 centimeters thick at one hole and 235 centimeters thick at another hole. How much thicker is the ice at the second hole?"],key:["623 kilometers (348 + 275 = 623). Listen for hundreds with hundreds, tens with tens, ones with ones, and for making a new ten and a new hundred.","264 kilometers (500 - 236 = 264). This one needs two decomposes, so watch the work.","595 meters (406 + 189 = 595)","73 centimeters thicker (235 - 162 = 73)"]}]},{id:5,title:"Ice Floe Facts",short:"Ice Floes",parts:[{std:["RI.2.1"],dur:95,dir:"Read about ice floes. Then answer each question out loud.",desc:"asking and answering what, who, how, and why questions about an informational text the student read",html:()=>passage("Ice Floes",FLOE),qs:["What is an ice floe?","Who climbs onto floes to rest?","How do scientists check a floe before they step on it?","Why does the team walk only on thick ice?","Your turn. Ask a question about ice floes. Start with who, what, where, when, why, or how."],key:["Sea ice that has cracked into a flat piece and floats on the water","Seals","They test it with a long pole.","A thin floe can tip.","Asks a question that is about the topic and starts with a question word (for example: How big can a floe get? Why does the sea freeze on top?)."]}]},{id:6,title:"Fix the Field Note",short:"Field Note",parts:[{title:"Say It Right",std:["L.2.1"],dur:110,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular past tense, irregular plural, reflexive pronoun, adverb, word order, joining two sentences)",qs:["Today the dogs run on the trail. Yesterday the dogs ____.","One foot, two ____.","I pulled my own sled all by ____.","Which word fits? The sled slid ____ down the icy hill. Is it quick or quickly?","Mix-up! Put these words in order to make a sentence: <b>rested / on the ice / the seal</b>","Join these two sentences with the word <b>and</b>: The wind blew. The flags shook."],key:["ran","feet","myself","quickly","The seal rested on the ice.","The wind blew, and the flags shook."]},{title:"Write It Right",std:["L.2.2"],dur:110,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters in place names and months, an apostrophe for a possessive and a contraction, a comma in a letter greeting, spelling two patterns)",qs:["Fix this sentence: <b>we flew over the arctic ocean in may</b>","The tent belongs to the pilot. Write the missing word: <b>the ____ tent</b>","This is the start of a letter. Write it and add the missing mark: <b>Dear Captain</b>","Write <b>do not</b> as one short word with an apostrophe.","Listen. Write the word your teacher says.","Listen. Write the second word your teacher says."],key:["We flew over the Arctic Ocean in May. (capital W to start, capital A and capital O in the ocean name, capital M in the month, and a period)","pilot’s (apostrophe before the s)","Dear Captain, (comma after Captain)","don’t (apostrophe where the o of not comes out)","Say: “Night. The lights glow at night.” The student writes night (igh).","Say: “Frozen. The frozen sea was white.” The student writes frozen (two syllables, long o)."]}]},{id:7,title:"Flags on the Trail",short:"Trail Flags",parts:[{std:["2.NBT.A.2"],dur:160,dir:"Count out loud.",desc:"counting within 1000 and skip-counting by 2s, 5s, 10s, and 100s",html:()=>`<p class="big" style="margin-top:0">The team plants a flag on the trail every 5 kilometers, so the counting goes 5, 10, 15, and on.</p>`,fig:()=>F.row([F.objects("flag",6),"Flags mark the route"]),qs:["Skip count by 5s from 70 to 110.","Skip count by 10s from 430 to 500.","Count by ones from 795 to 804.","Skip count by 100s from 240 to 840.","Skip count by 2s from 86 to 100."],key:["70, 75, 80, 85, 90, 95, 100, 105, 110. Watch the jump past 95.","430, 440, 450, 460, 470, 480, 490, 500","795, 796, 797, 798, 799, 800, 801, 802, 803, 804. Watch the jump past 799.","240, 340, 440, 540, 640, 740, 840","86, 88, 90, 92, 94, 96, 98, 100"]}]},{id:8,title:"Expedition Story",short:"Write",parts:[{std:["W.2.3"],n:4,label:"checks met",dur:180,dir:WRITE_DIR,desc:"a short narrative with events in order, details about actions and feelings, time words, and an ending",html:()=>`<p class="big">You are on the polar team. One morning you step out of your tent and find animal tracks in the snow. Write a story about what happens next. Tell what happened in order. Tell what you did and how you felt. Write 4 sentences.</p>${pills("First","Then","After that","In the end")}`,key:["Tells about one event or a short set of events in order","Includes details about actions, thoughts, or feelings","Uses time words like first, then, after that, or in the end","Ends with a sentence that wraps up the story"]}]},{id:9,title:"Ration Count",short:"Rations",parts:[{std:["2.OA.A.1"],dur:130,dir:"Each problem has two steps. Solve it on your paper and say your answer.",desc:"two-step addition and subtraction word problems within 100",html:()=>`<p class="big" style="margin-top:0">Rations are the food the team packs for each day. Fuel is what the camp stove burns to melt snow into water.</p>`,qs:["The team had 45 ration bars. They ate 17 bars the first week and 12 bars the second week. How many bars are left?","One dogsled carries 8 crates. A second dogsled carries 9 crates. The team unloads 6 crates at the weather station. How many crates are still on the sleds?","Spot the mistake. There were 60 liters of fuel. The team used 25 liters, then a plane brought 15 more liters. A helper wrote 60 - 25 - 15 = 20. What did the helper do wrong? Fix it."],key:["16 bars (45 - 17 = 28, then 28 - 12 = 16)","11 crates (8 + 9 = 17, then 17 - 6 = 11)","The helper took away the 15 liters instead of adding them. 60 - 25 = 35, then 35 + 15 = 50 liters."]}]},{id:10,title:"Radio Check",short:"Radio",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:70,read:LIGHTS,dir:"Listen first. Then answer your teacher’s questions out loud.",desc:"recounting and describing key ideas and details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ic("antenna",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read a radio report about lights in the polar sky.</p>`,key:["Ask: “What do people call the lights that move across the sky near the North Pole?” (the northern lights)","Ask: “Describe what the glow can look like.” (a curtain blowing in the wind; green and pink waves of light)","Ask: “Where do the lights come from?” (tiny bits of energy from the sun that crash into the air high above the earth and make it glow)","Say: “Tell me two more things you learned.” (any two: they show on clear winter nights, they are too far up to make any sound, the same thing near the South Pole is called the southern lights)"]},{title:"Tell Me About It",std:["SL.2.4"],n:4,label:"checks met",dur:55,dir:"Tell about it out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with facts and details, in clear complete sentences",html:()=>`<p class="big">Tell me about a time you had to get ready for cold weather or hot weather. Where were you going? What did you put on or pack? What happened?</p>${pills("First","Next","Last")}`,key:["Tells what happened in an order that makes sense","Gives facts that fit (where, when, who, or what)","Uses describing details (how it looked, felt, or sounded)","Speaks in complete sentences, loud and clear enough to hear"]}]},{id:11,title:"Measure the Ice",short:"Measure",parts:[{std:["2.MD.A.1"],dur:170,dir:"Answer out loud. For the last one, get a ruler and measure.",mats:["a ruler"],desc:"measuring length with a ruler and choosing the right measuring tool",html:()=>`<p class="big" style="margin-top:0">An ice core is a round stick of ice the team drills out and measures. A snow tube holds a sample of snow.</p>`,fig:()=>F.row([F.ruler({length:8,item:5,itemLabel:"ice core"}),"Ruler in inches"],[F.ruler({length:12,item:9,itemLabel:"snow tube"}),"Ruler in centimeters"]),qs:["Look at the first ruler. How long is the ice core?","Look at the second ruler. How long is the snow tube?","The team needs to know how wide the tent floor is. Would a ruler or a meter stick be a better tool? Why?","You want to measure all the way around a round fuel drum. Would you use a yardstick or a measuring tape? Why?","Get a ruler. Measure a spoon. How long is it?"],key:["5 inches","9 centimeters","A meter stick. The floor is much longer than a ruler, so a ruler would have to be moved many times.","A measuring tape, because it bends around the curve of the drum.","Lines up one end at 0, reads the nearest whole inch or centimeter, and says the unit."]}]},{id:12,title:"Trail Sign Reading",short:"Trail Signs",parts:[{std:["RF.2.3"],n:3,dur:60,dir:"Read each line out loud. Sound out any word that is tricky.",desc:"applying grade-level phonics and word-analysis skills to decode words in text",html:()=>`<ol class="qlist" style="font-size:1.6rem;line-height:1.9"><li>The sled dogs turned north and climbed the icy ridge.</li><li>We unpacked three crates and stacked them beside the tent.</li><li>The frozen sea looked silver in the moonlight.</li></ol>`,key:["Line 1: listen for the r-controlled or in north, the long i and the y that says long e in icy, and the dge ending in ridge.","Line 2: listen for the prefix un in unpacked, the ed ending on unpacked and stacked, the ee team in three, and the two syllables with silent e in beside.","Line 3: listen for silent e long o in frozen, the two syllables in silver, and the compound word moonlight."]}]},{id:13,title:"Weather Station Log",short:"Weather Log",parts:[{std:["W.2.8"],dur:120,dir:"Use the log to answer. Say the first two answers out loud. Write number 3 on your paper and hold it up. Then say number 4.",desc:"gathering information from a provided log and recalling information from experience to answer questions",html:()=>`<p class="big" style="margin-top:0">At the weather station every temperature is below zero. On the thermometer, the numbers below zero are colder. 20 below zero is colder than 9 below zero.</p>`,fig:()=>F.row([thermo(-15),"This reads 15 below zero"],LOG),qs:["Use the log. Which day was the coldest?","Which days had strong wind?","A friend asks, “Was Monday or Tuesday colder?” Write one sentence that answers your friend. Use the log.","Now use what you remember. Think of the coldest day you can remember where you live. What did you wear or do to stay warm? Say it in a sentence."],key:["Wednesday, at 20 below zero","Tuesday and Thursday","The sentence says Monday was colder and uses the numbers from the log (Monday was 12 below zero and Tuesday was only 9 below zero).","Tells one thing remembered from a real cold day, in a sentence that answers the question (for example: I put on two pairs of socks before school.)."]}]},{id:14,title:"Logbook Check",short:"Logbook",parts:[{std:["2.NBT.B.7"],dur:140,dir:"Solve on your paper. Show your work and hold it up.",desc:"subtracting and adding three-digit numbers with decomposing and composing, and finding an error in a written method",qs:["One depth reading was 740 meters. The next reading was 358 meters. How much less deep was the second reading?","The team pulled 567 kilograms of gear on the first sled and 276 kilograms on the second sled. How many kilograms in all?","Spot the mistake. A helper worked out 532 - 148 and wrote 416. What went wrong? Give the right answer."],key:["382 meters (740 - 358 = 382). Two decomposes are needed here.","843 kilograms (567 + 276 = 843)","The helper took the smaller digit from the bigger digit in each column instead of decomposing a ten and a hundred. The right answer is 384."]}]},{id:15,title:"Two Shovels",short:"Shovels",parts:[{std:["RL.2.2"],n:3,dur:65,dir:"Read the story out loud. Then answer each question out loud.",desc:"recounting a short story and naming the lesson it teaches",html:()=>passage("Two Shovels",SHOVELS),qs:["Retell this story. Tell me the beginning, the middle, and the end.","What lesson does this story teach?","Which part of the story shows that lesson best?"],key:["Nils shovelled the path alone and had only half of it done by noon. The next morning Ada brought a second shovel. They worked from both ends and finished quickly. Count it correct when the three parts are there in order.","A job goes faster when people share the work. Any wording of that idea counts, such as: two people working together finish sooner.","The part where the two of them start at opposite ends and meet in the middle, and the path is done before the kettle boils."]}]},{id:16,title:"Odd or Even",short:"Odd Even",parts:[{std:["2.OA.C.3"],n:3,dur:55,dir:"Count each group. Answer out loud. Write the last one on your paper.",desc:"deciding whether a group is odd or even and writing an even number as a sum of two equal addends",fig:()=>F.row([F.objects("box",13,7),"Crates"],[F.objects("snowflake",16,8),"Snow samples"]),qs:["Count the crates. Is that number odd or even? How do you know?","Count the snow samples. Is that number odd or even?","Write an equation that shows the number of snow samples as two equal addends."],key:["13, odd. Pairing them up leaves one crate with no partner, and counting by 2s skips over 13.","16, even. Every snow sample has a partner.","8 + 8 = 16"]}]},{id:17,title:"Crates in Rows",short:"Rows",parts:[{std:["2.OA.C.4"],n:2,dur:50,dir:"Look at each block of crates. Answer out loud and write the equation on your paper.",desc:"finding the total in a rectangular array and writing it as a sum of equal addends",fig:()=>F.row([F.array(4,5,"box"),"Yard A"],[F.array(3,4,"box"),"Yard B"]),qs:["Yard A. How many crates in all? Write an addition equation with equal addends.","Yard B. How many crates in all? Write an addition equation with equal addends."],key:["20 crates. 5 + 5 + 5 + 5 = 20, one addend for each of the 4 rows. 4 + 4 + 4 + 4 + 4 = 20 by columns is also correct.","12 crates. 4 + 4 + 4 = 12 by rows, or 3 + 3 + 3 + 3 = 12 by columns."]}]},{id:18,title:"Four Hundred Six",short:"Place Value",parts:[{std:["2.NBT.A.1","2.NBT.A.3"],n:3,dur:55,dir:"Look at the blocks. Answer out loud. Write the last two on your paper.",desc:"reading a three-digit number from blocks, writing it in expanded form, and writing its number name",fig:()=>F.row(F.blocks(4,0,6)),qs:["Each big square is a hundred, each tall bar is a ten, and each little square is a one. What number do the blocks show?","Write that number in expanded form.","Write that number in words."],key:["406. Four hundreds, no tens, and six ones. If the student says 46, point at the empty tens place and ask what belongs there. (2.NBT.A.1)","400 + 6. Writing 400 + 0 + 6 is also correct. (2.NBT.A.3)","four hundred six (2.NBT.A.3)"]}]},{id:19,title:"Camp Clocks",short:"Clocks",parts:[{std:["2.MD.C.7"],n:3,dur:50,dir:"Look at the two clocks. Answer out loud.",desc:"telling time to the nearest five minutes, using a.m. and p.m., and knowing minutes in an hour",fig:()=>F.row([F.clock(4,15,180),"Clock A"],[F.clock(9,45,180),"Clock B"]),qs:["What time does Clock A show?","What time does Clock B show?","The team eats breakfast at 7:30 in the morning. Is that a.m. or p.m.? And how many minutes are in one hour?"],key:["4:15, or a quarter past 4","9:45, or a quarter to 10. The hour hand sits close to the 10, but it has not passed it, so the hour is still 9.","a.m., and 60 minutes in an hour"]}]},{id:20,title:"Coins in the Pocket",short:"Coins",parts:[{std:["2.MD.C.8"],n:2,dur:50,dir:"Look at the coins. Answer out loud.",desc:"finding the value of a set of coins and solving a money problem with the cent symbol",fig:()=>F.coins(["Q","Q","D","N","P","P"]),qs:["Mira still has these coins in her coat pocket from home. How much money is that in all?","On the way home she spends 40¢ at the airfield counter. How much does she have left?"],key:["67¢. Two quarters make 50¢, the dime makes 60¢, the nickel makes 65¢, and the two pennies make 67¢.","27¢ (67¢ - 40¢ = 27¢). Look for the ¢ symbol in the written answer."]}]},{id:21,title:"Draw the Core Graph",short:"Graph It",parts:[{std:["2.MD.D.10"],n:3,dur:55,dir:"Look at the table. Draw the graph on your paper and hold it up. Then answer out loud.",desc:"drawing a bar graph with a single-unit scale from a table and answering questions about it",fig:()=>CORE_LOG,qs:["Draw a bar graph of this table on your paper. Give it a title, label the three days, and number the side by ones.","How many more cores were drilled on Tuesday than on Wednesday?","How many cores were drilled in all three days?"],key:["A bar graph with three bars, 6 for Monday, 9 for Tuesday and 4 for Wednesday, a title, the days labelled, and a side scale counting by ones. A picture graph with one symbol for each core is also correct.","5 more (9 - 4 = 5)","19 cores (6 + 9 + 4 = 19)"]}]},{id:22,title:"Camp Shapes",short:"Shapes",parts:[{std:["2.G.A.1"],n:3,dur:55,dir:"Look at the five shapes. Answer out loud. Draw the middle one on your paper.",desc:"naming shapes by their number of sides and angles, drawing a shape to a given attribute, and naming a cube",fig:()=>shapeSetFig(),qs:["Name shapes A, B, C and D.","Draw a shape that has exactly 6 angles. What is that shape called?","Shape E is a solid, not a flat shape. What is it called, and how many equal faces does it have?"],key:["A is a triangle (3 sides, 3 angles), B is a quadrilateral (4 sides, 4 angles), C is a pentagon (5 sides, 5 angles), D is a hexagon (6 sides, 6 angles).","A closed shape with exactly 6 straight sides and 6 angles. It is called a hexagon. The drawing does not have to be neat or regular.","A cube. It has 6 equal faces, and every face is a square."]}]},{id:23,title:"Sled or Snowmobile",short:"My Opinion",parts:[{std:["W.2.1"],n:4,label:"checks met",dur:70,dir:WRITE_DIR,desc:"a short opinion piece with the topic, an opinion, a reason, a linking word, and an ending",html:()=>`<p class="big">Which is the better way to move gear across the snow at base camp: a dogsled or a snowmobile? Write what you think and tell why. Write 2 or 3 sentences.</p>${pills("I think","because","also","So")}`,key:["Names the topic the writing is about: the best way to move gear across the snow","States an opinion, which of the two the student would pick","Gives at least one reason that supports the opinion, such as dogs do not run out of fuel, or a snowmobile is faster","Uses a linking word such as because, and, or also, and ends with a sentence that wraps it up"]}]},{id:24,title:"What Is at Base Camp",short:"Camp Facts",parts:[{std:["W.2.2"],n:4,label:"checks met",dur:70,dir:WRITE_DIR,desc:"a short informative piece with the topic, two facts, one definition, and an ending",html:()=>`<p class="big">Write about base camp for someone who has never seen one. Tell 2 facts about it and explain what one polar word means. Write 2 or 3 sentences.</p>${pills("Base camp is","One fact is","A ___ is","That is")}`,key:["Names the topic: base camp, or what a polar team keeps at base camp","Gives at least 2 true facts, such as the team sleeps there, the food is kept there, tents are put up there, or the weather station log is kept there","Explains what one polar word means, such as: base camp is where the team sleeps and keeps its food, an ice core is a round stick of ice the team drills out, or an ice floe is a flat piece of floating sea ice","Ends with a sentence that wraps it up, such as: That is what base camp is like"]}]},{id:25,title:"Three Trays in the Camp Hut",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">The team grows cress in trays in the camp hut, because nothing green grows outside. Three trays were started on the same day.</p>
     <table class="bigTable"><tr><th>Tray</th><th>What it got</th><th>After ten days</th></tr>
     <tr><td>A</td><td>lamp light and water</td><td>thick green cress, 6 centimeters tall</td></tr>
     <tr><td>B</td><td>lamp light, no water</td><td>a few seeds split open, nothing grew</td></tr>
     <tr><td>C</td><td>water, lamp switched off</td><td>pale stalks, 4 centimeters, no green</td></tr></table>
     <div class="figure">${ic("sprout",88)}${ic("lamp",88)}</div>`,qs:["Which tray grew best, and what did it get?","Tray C got water every day. Why did nothing in it turn green?","You want to test only whether cress needs the lamp. Name two things you would keep the same, and name the one thing you would change."],key:["Tray A. It got both the lamp light and water.","The lamp was switched off, so it had no light. A plant needs light to make its food, and that is also what makes it green.","Keep the same: the same seeds, the same tray, the same soil, the same water, the same room. Change only one thing: one tray under the lamp and one tray with the lamp off. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it moves pollen",html:()=>`<p class="big">The polar summer is short. Bumblebees crawl over the low arctic flowers. Pollen sticks to the hairs on their bodies. It rubs off again. That happens on the next flower they visit.</p>
     <div class="figure">${ic("bee",88)}${ic("purpleFlower",88)}</div>
     <p class="big">Draw a model you could really build out of things in a camp hut, such as a bottle brush or a woolly sock pulled over a stick, that would pick pollen up from one flower and rub it onto another.</p>`,qs:["Draw your model. Label the part that the pollen sticks to.","Which animal job does your model copy, and why does your model need a rough or hairy part instead of a smooth one?"],key:["Any model with a rough, hairy or fuzzy carrying part: a bottle brush, a woolly sock on a stick, a pipe cleaner, a strip of felt. The labelled carrying part is what to look for.","It copies a bee carrying pollen between flowers. A rough or hairy part catches and holds the tiny grains, and a smooth part would let them slide straight off, so nothing would get carried."]}]},{id:26,title:"The Rocky Shore and the Snow Plain",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">The team wrote down every living thing they found in two places, spending one hour in each.</p>
     <table class="bigTable"><tr><th>The rocky shore</th><th>The snow plain inland</th></tr>
     <tr><td>4 kinds of seaweed</td><td>1 kind of lichen on a bare rock</td></tr>
     <tr><td>2 kinds of moss and lichen</td><td>fox tracks</td></tr>
     <tr><td>1 seal, 3 kinds of seabird</td><td></td></tr>
     <tr><td>2 kinds of small shore creature in the pools</td><td></td></tr></table>
     <div class="figure">${ic("seal",80)}${ic("snowflake",80)}</div>`,qs:["How many kinds of living things are on the rocky shore list?","Which place has more different kinds of living things?","The shore has open water and bare rock, and the snow plain is deep snow for miles. Explain how that could make the two lists so different."],key:["12. Four seaweeds, two mosses and lichens, one seal, three seabirds and two shore creatures.","the rocky shore","The shore has water, food in the sea, and bare rock where seaweed and lichen can hold on, so many kinds of living thing can get what they need. The snow plain has almost no food and nothing for a plant to grow on. Listen for the link between what a place gives and what lives there."]}]},{id:27,title:"Minutes, or Thousands of Years",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about this coast, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>the camp radio log</td><td>At eleven in the morning a crack opened right across the floe and in a few minutes the two pieces were a boat length apart.</td></tr>
     <tr><td>a chapter in the expedition handbook</td><td>The long valley behind the bay was scraped out by a glacier that crept down it over thousands of years.</td></tr></table>`,qs:["Which note tells about a change that happened in minutes?","Which note tells about a change that took thousands of years?","Name one more change to the Earth that happens quickly, and one that happens slowly."],key:["The radio log, the crack opening across the floe in a few minutes.","The handbook chapter, the valley scraped out by a glacier over thousands of years.","Quick: a rockfall, a flood, a crack opening in ice, a bank falling in. Slow: a river cutting a canyon, a cliff wearing back, a mountain wearing down. The answer has to name a change to the Earth itself, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">Almost everything the team can see is water in one form or another.</p>
     <div class="figure">${ic("snowflake",80)}${ic("wave",80)}${ic("drop",80)}</div>`,qs:["Name three places around this camp where you would find water.","The sea here is salty. Where does the team get fresh water from instead?","Sort these four into solid water and liquid water: the glacier, the melt pool on the ice, the snow on the tent, the sea."],key:["Any three: the sea, the sea ice, the glacier, the snow on the ground, a melt pool, clouds, frost on the gear.","By melting snow or glacier ice, which is fresh and not salty. Accept: a stream of melt water.","Solid: the glacier and the snow on the tent. Liquid: the melt pool and the sea."]}]},{id:28,title:"Holding the Camp Ground, and a Map of It",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things built to stop wind from changing the shape of the ground",html:()=>`<p class="big">Wind scours the snow out from under the tents and leaves bare holes. Two screens were tried and the depth of the holes was measured after three windy days.</p>
     <table class="bigTable"><tr><th>What stood on the windy side</th><th>How deep the holes were</th></tr>
     <tr><td>nothing</td><td>30 centimeters</td></tr>
     <tr><td>a wall of cut snow blocks</td><td>4 centimeters</td></tr>
     <tr><td>a canvas screen on two poles</td><td>12 centimeters, and the screen flapped loudly</td></tr></table>`,qs:["Which screen held the ground best?","How do you know, using the numbers in the chart?","The canvas screen can be rolled up and carried, and the snow wall has to be cut and built each time. When would the team still choose the canvas?"],key:["the wall of cut snow blocks","The holes were only 4 centimeters deep behind the snow wall, 12 centimeters behind the canvas, and 30 centimeters with nothing there. The reason must come from the numbers.","When they are only staying one night, or moving every day, so there is no time to cut and build a wall. Any reason about carrying it or being quick counts."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the coast around base camp. Put in the high ice cap, the flat plain, the bay, and the melt stream that runs down to it. Add a key that says which is which.</p>
     <div class="figure">${ic("mountain",88)}${ic("map",88)}${ic("tent",88)}</div>`,qs:["Draw your model map with the ice cap, the flat plain, the bay and the melt stream on it.","Show me your key. Which parts are land or ice and which parts are liquid water?","Water runs downhill. Looking at your own map, which way does the melt stream run?"],key:["All four on the page and told apart by shape or colour: the ice cap high, the plain left flat, the bay as an opening of water in the coast, the stream as a line.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","Down off the ice cap towards the bay, which is the lowest part of their map. The answer has to match their own drawing, so follow their finger."]}]},{id:29,title:"Sorting the Expedition Kit",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">Four things out of a kit crate, and what the team wrote about each one.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What they wrote</th></tr>
     <tr><td>a mug</td><td>steel</td><td>hard, shiny, gets very cold to hold</td></tr>
     <tr><td>a sock</td><td>wool</td><td>soft, bends easily, keeps a foot warm</td></tr>
     <tr><td>a thermometer tube</td><td>glass</td><td>hard, smooth, you can see through it</td></tr>
     <tr><td>a boot sole</td><td>rubber</td><td>bends, grips the ice, keeps water out</td></tr></table>`,qs:["Sort the four items into a hard group and a group that bends.","Two of them keep the cold away from your skin. Which two, and what do they have in common?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Hard: the steel mug and the glass thermometer tube. Bends: the wool sock and the rubber boot sole.","The wool sock and the rubber boot sole. Both of them bend, and both are worn next to the body rather than held. Accept any answer that groups them by being soft or bendy rather than by being metal or glass.","Any property that can be seen or felt and that really splits the four: see through or not, shiny or dull, grips or slides, soaks water up or keeps it out. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The team needs a facing for the bottom of a sled runner. Three materials were each dragged 100 meters over cold snow with the same load.</p>
     <table class="bigTable"><tr><th>Facing</th><th>Pull needed</th><th>After the 100 meters</th></tr>
     <tr><td>bare wood</td><td>heavy</td><td>rough and scratched</td></tr>
     <tr><td>steel strip</td><td>light</td><td>cracked in two places in the cold</td></tr>
     <tr><td>hard plastic strip</td><td>light</td><td>no damage</td></tr></table>`,qs:["Which facing should go on the runner?","Which two pieces of the chart make you sure?","The steel was just as easy to pull. Why is it still the wrong choice out here?"],key:["the hard plastic strip","It needed only a light pull and it had no damage after 100 meters. Both columns have to be used, not just one.","It cracked in two places in the cold. A runner that breaks out on the trail is no use however well it slides, and the team would be a long way from camp."]}]},{id:30,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">The weather station has a mast. It is made of 3 metal poles. It has 6 clamps. The team unclamped it. They laid the poles flat. They did it before a storm came through.</p>
     <div class="figure">${ic("antenna",88)}${ic("board",88)}</div>`,qs:["The mast is gone. Are the poles and clamps gone too? What is lying flat on the snow?","Build something new in your head out of those 3 poles and 6 clamps. What is it, and how do the pieces go together?"],key:["No. All 3 poles and all 6 clamps are still there. They are the same pieces, just not clamped together as a mast any more.","Any real thing from 3 poles and 6 clamps: a tripod to hang a pot over a stove, a flag pole, a frame for a tent door, a drying rack, a marker for the trail. Listen for how the pieces join, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened on the camp stove within an hour of each other.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A pot of packed snow was heated and became a pot of water.</td></tr>
     <tr><td>A pan of oats was cooked into thick porridge.</td></tr></table>
     <div class="figure">${ic("pan",80)}${ic("soup",80)}</div>`,qs:["Set the pot of water outside the tent. What happens to it?","Set the pan of porridge outside the tent. Does it turn back into dry loose oats?","Which of the two changes can be undone, and what is your evidence?"],key:["It freezes into ice, and heating it again would melt it back.","No. It stays thick porridge. It goes cold and hard but it is still porridge, not dry loose oats.","The snow and water change can be undone. The evidence is that the water freezes again outside and melts again on the stove, while the cooked porridge never goes back to dry oats however cold it gets. Listen for the student using what happened, not just saying yes or no."]}]},{id:31,title:"The Thermometer That Blows Over",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The thermometer has to stand outside the tent. It stands there all day. Then the team can write down the temperature. They do it every hour. It stands on three thin legs. They are pushed into the snow. Every time the wind gets up it leans over. Then it falls flat. The reading for that hour is lost.</p>`,qs:["What is the problem the team wants to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The thermometer stand blows over in the wind, so readings get missed. Naming the falling over, not the missed readings alone, is the problem.","Any real question: how heavy is the thermometer, how deep do the legs go, how hard does the wind blow, how wide are the legs apart, is the snow soft or packed. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw a stand that would hold the thermometer up in a strong wind. Think hard about its shape.</p>
     <div class="figure">${ic("thermometer",88)}${ic("box",88)}</div>`,qs:["Draw your stand.","Tell me how the shape of what you drew keeps it standing."],key:["Any design that could really stand in wind: three or four legs spread wide, a wide flat base, a box of packed snow around the foot, long legs pushed deep, guy lines out to pegs.","The shape is the part being checked. Something like: the wide legs make it hard to tip, the heavy base holds the bottom down, the deep legs cannot pull out, the lines pull it from all sides at once."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">Both stands were used for five windy days.</p>
     <table class="bigTable"><tr><th>Stand</th><th>Times it fell over</th><th>Readings missed</th></tr>
     <tr><td>wide legs set in a block of packed snow</td><td>0</td><td>0</td></tr>
     <tr><td>three thin legs with guy lines</td><td>2</td><td>6</td></tr></table>`,qs:["Which stand worked better?","How do you know? Use both columns."],key:["the wide legs set in a block of packed snow","It never fell over and no readings were missed, while the thin legged stand fell twice and 6 readings were missed. Both columns have to be used, not just the falling over."]}]},{id:32,title:"Expeditions Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the front of the expedition journal.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>This morning the team called home on the radio and gave the weather.</td></tr>
     <tr><td>2</td><td>A hundred years ago, a team coming here heard nothing from home for two whole years.</td></tr>
     <tr><td>3</td><td>Yesterday the team measured the thickness of the ice at four places on the bay.</td></tr>
     <tr><td>4</td><td>Long before there were engines, the only way to carry supplies over the ice was on a sledge pulled by dogs or by people.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Pick one of the long ago lines and say what is different about the way it is done now."],key:["Lines 2 and 4, hearing nothing from home for two years and pulling sledges by dog or by hand.","Lines 1 and 3, the radio call this morning and measuring the ice yesterday.","Either one: a team today can talk to home by radio any day instead of waiting two years; supplies can be carried by a machine or flown in instead of being pulled by dogs or by people."]}]},{id:33,title:"Where Things Are at Base Camp",short:"Camp Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">Base camp, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("mountain",46)} ice cap</td><td>${ic("antenna",46)} weather station</td><td>${ic("telescope",46)} lookout rock</td></tr>
     <tr><th>B</th><td>${ic("box",46)} supply crates</td><td>${ic("tent",46)} sleeping tents</td><td>${ic("sled",46)} sled park</td></tr>
     <tr><th>C</th><td>${ic("wave",46)} the bay</td><td>${ic("flag",46)} trail start</td><td>${ic("seal",46)} seal rocks</td></tr></table>
     <p class="big">${ic("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>`,qs:["Give the exact square the sleeping tents are in, using their letter and number.","What is directly north of the sleeping tents?","Is the bay east or west of the seal rocks?","Which square is between the supply crates and the sled park?"],key:["B2","the weather station, in square A2","west. The bay is in C1 and the seal rocks are in C3, so the bay is to the left, which is west.","B2, the sleeping tents"]}]},{id:34,title:"Rules, Rations and Trade",short:"Rules and Trade",parts:[{std:["HSS-2.3"],n:5,dur:105,dir:"Answer out loud.",desc:"telling who makes rules here and how countries make rules together",html:()=>`<p class="big">Out here the team follows its own camp rules. Also rules their countries agreed to.</p>
     <p class="big">Countries can sign a written agreement. It is signed between them. That agreement is called a treaty. Getting to a treaty takes talking. The work of talking between countries is called diplomacy. Countries do not always settle things that way. Sometimes they trade with each other. Sometimes they visit and learn from each other. Sometimes they send their armies instead. That is called using military force. A treaty is a way to settle a problem. Countries use it without doing that.</p>
     <div class="figure">${ic("flag",80)}${ic("books",80)}</div>`,qs:["Who makes the laws for the whole country we live in? The people we vote for, or whoever shouts loudest?","Many countries signed an agreement that this place would be used only for science and that nobody would own it. What is a written agreement between countries called?","What is the work of talking between countries called, the talking that leads to an agreement?","Name one other way countries deal with each other, besides signing an agreement.","In some other countries the leader is a king or a queen who was born into the job. In our country, how do we get our leaders?"],key:["the people we vote for. Accept: Congress, the lawmakers we elect. (HSS-2.3)","A treaty (HSS-2.3)","Diplomacy (HSS-2.3)","Any one from the page: trading with each other, visiting and learning from each other, or sending armies, which is called using military force. (HSS-2.3)","We vote for them. Any answer that says the people choose their leaders by voting counts. (HSS-2.3)"]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"telling goods from services, spending a set amount, and saying why people trade",html:()=>`<p class="big">Base camp has no shop, so the team keeps a swap board. Each thing is worth a number of ration tokens.</p>
     <table class="bigTable"><tr><th>On the swap board</th><th>Tokens</th></tr>
     <tr><td>a bar of dried fruit</td><td>3</td></tr>
     <tr><td>a spare pair of dry socks</td><td>5</td></tr>
     <tr><td>a tin of hot cocoa</td><td>2</td></tr>
     <tr><td>someone to take your turn on the night weather watch</td><td>4</td></tr></table>
     <div class="figure">${ic("cocoa",72)}${ic("box",72)}</div>`,qs:["Three things on this board are goods and one is a service. Which one is the service, and how do you know?","You have 6 tokens. Name two things you could swap for, and say what you give up.","The cook can mend a stove but cannot sew, and the radio operator can sew. Why do they trade jobs instead of each doing everything?"],key:["Taking your turn on the night weather watch. It is work someone does for you, not a thing you keep.","Any pair at 6 tokens or less: dried fruit and cocoa is 5, socks and cocoa is 7 and is too many, dried fruit and the night watch is 7 and is too many. Cocoa and cocoa is allowed if they say so. The giving up is the part to listen for.","Because each of them is good at a different thing, so trading gets both jobs done well and faster than each one learning everything. Accept: it saves time, you get what you cannot do yourself."]}]},{id:35,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about her. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Marie Curie grew up in Poland. At that time girls there were not allowed in. The universities would not take them. She saved for years. She moved to France. She studied science there. She was living on almost nothing. With her husband she worked in a shed. It was cold and leaky. She stirred heavy pots of rock. She did it for months on end. She found two new materials. Nobody had known about them. She was the first woman ever to win it. The Nobel Prize went to her. Then she won a second one. In a war she drove vans. They were fitted with machines. She had helped make them. So doctors could see inside. They could see a hurt arm or leg. Then they could set it properly.</p>
     <div class="figure">${ic("star",80)}${ic("thermometer",80)}</div>`,qs:["What did Marie Curie find after months of work in the shed?","Which word fits her best from what you read: persistent, lazy, or careless? Say why.","Name one way her work made a difference to other people."],key:["Two materials nobody had known about before.","persistent. Any reason taken from the text: she stirred heavy pots for months, she saved for years to get to a university that would take her, she kept going in a cold leaky shed.","Any answer from the text: doctors could see inside a hurt arm or leg and set it properly, she showed that a woman could win the top prize in science, she won two Nobel Prizes and opened the door for others."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Long Polar Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each long word out loud.",html:()=>`<div style="text-align:center">${["expedition","snowmobile","thermometer"].map(w=>`<p class="huge" style="font-size:clamp(2.4rem,8vw,4.4rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["expedition (ex-pe-di-tion)","snowmobile (snow-mo-bile)","thermometer (ther-mom-e-ter)"]},3:{id:"L3",title:"Level Up: Show Me the Words",std:["RL.3.1"],needs:["RL.2.1"],n:2,dir:"Answer out loud. Then read the words from the story that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${TRAIL}</p><ol class="qlist"><li>How do you know the team could find the way back at night? Read the part of the story that shows it.</li><li>How do you know the morning was very cold? Read the part of the story that shows it.</li></ol>`,key:["Says the red flags marked the trail, and reads the line about red showing up well on white snow so the team could find the way back.","Says the air was freezing, and reads the line about her breath making little clouds."]},5:{id:"L5",title:"Level Up: Prove It",std:["RI.3.1"],needs:["RI.2.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${FLOE}</p><ol class="qlist"><li>How do scientists know a floe is safe to step on? Read the part of the text that shows it.</li><li>Are all ice floes the same size? Read the part of the text that shows your answer.</li></ol>`,key:["Says they check it first, and reads the line about testing a floe with a long pole before stepping on it.","No. Reads the lines about some floes being smaller than a bed and others being as wide as a soccer field."]},6:{id:"L6",title:"Level Up: Grown-Up Grammar",std:["L.3.1"],needs:["L.2.1"],n:2,dir:"Say each answer out loud.",html:()=>`<ol class="qlist"><li>One husky is strong. Eight huskies pulling together are ____ than one husky.</li><li>Join these two sentences with the word <b>because</b>: We stayed in the tent. The wind was too strong.</li></ol>`,key:["stronger (the comparative form)","We stayed in the tent because the wind was too strong."]},9:{id:"L9",title:"Level Up: Depot Trip",std:["3.OA.D.8"],needs:["2.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer and how you got it.",html:()=>`<p class="big">Each sled carries 7 crates. The team pulls 4 sleds to the depot and leaves every crate there. Then a plane takes 5 crates away. How many crates are at the depot now?</p>`,key:["23 crates (4 x 7 = 28, then 28 - 5 = 23)"]}};const PASSAGE_STD=["RL.2.1","RI.2.1","RL.3.1","RI.3.1","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let chartOn={},pvVal=["",""],blk=[0,0,0];function chartHtml(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${chartOn[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function matSvg(h,t,o){return F.blocks(h,t,o)}function blkHtml(){const b=(k,t)=>`<button class="chip" data-b="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]+blk[2]?matSvg(blk[0],blk[1],blk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} hundreds, ${blk[1]} tens, and ${blk[2]} ones on the mat.</p>`}function blkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")blk=[0,0,0];else if(k==="to"){if(blk[2]>=10&&blk[1]<19){blk[2]-=10;blk[1]++}}else if(k==="th"){if(blk[1]>=10&&blk[0]<9){blk[1]-=10;blk[0]++}}else if(k==="bt"){if(blk[1]>=1&&blk[2]<=9){blk[1]--;blk[2]+=10}}else if(k==="bh"){if(blk[0]>=1&&blk[1]<=9){blk[0]--;blk[1]+=10}}else blk[i]=Math.max(0,Math.min(MAX[i],blk[i]+(k[1]==="+"?1:-1)))}const STARTERS={"W.2.3":["One morning, ____.","First, ____.","Then, ____.","After that, ____.","In the end, ____."],"W.2.8":["The log says ____.","On Monday it was ____.","The coldest day was ____.","I remember ____."],"W.2.1":["I think ____ is better.","One reason is because ____.","Also, ____.","So that is why I would pick ____."],"W.2.2":["Base camp is ____.","One fact is ____.","Another fact is ____.","A ____ is ____.","That is what base camp is like."]};function sentHtml(st){const k=st&&st.parts&&st.parts[0]&&st.parts[0].std&&st.parts[0].std[0]||"W.2.3";return`<ul class="starters">${(STARTERS[k]||STARTERS["W.2.3"]).map(x=>`<li>${x}</li>`).join("")}</ul>`}let tpsNlStart="",tpsNlHops=[],tpsNlShown={};function tpsNlSvg(){if(tpsNlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+tpsNlStart];tpsNlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;tpsNlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+tpsNlStart||tpsNlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+tpsNlStart?"":`data-tv="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function tpsNlHtml(){const j=d=>`<button class="chip" data-tj="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="tpsNlStart" value="${tpsNlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-tj="u">Undo</button><button class="chip" data-tj="x">Clear</button></div><div class="tool-scroll" id="tpsNlBox" style="text-align:center">${tpsNlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function tpsNlBind(b,r){const box=()=>b.querySelectorAll("[data-tv]").forEach(g=>g.onclick=()=>{tpsNlShown[g.dataset.tv]=!tpsNlShown[g.dataset.tv];r()});const inp=b.querySelector("#tpsNlStart");inp.oninput=()=>{tpsNlStart=inp.value.replace(/[^0-9]/g,"");tpsNlShown={};b.querySelector("#tpsNlBox").innerHTML=tpsNlSvg();box()};b.querySelectorAll("[data-tj]").forEach(x=>x.onclick=()=>{const k=x.dataset.tj;if(k==="x"){tpsNlHops=[];tpsNlShown={}}else if(k==="u")tpsNlHops.pop();else if(tpsNlStart!==""&&tpsNlHops.length<10)tpsNlHops.push(+k);r()});box()}function tpsCoinHtml(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;align-items:flex-end">${[["Q","25¢"],["D","10¢"],["N","5¢"],["P","1¢"]].map(([k,v])=>`<span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.coin(k)}<b style="font-size:1.1rem">${v}</b></span>`).join("")}</div><p class="small" style="margin:8px 0 0">This chart gives the value of each coin. The student still does the adding and still writes the cent sign.</p>`}function tpsClockHtml(){return F.row([F.clock(8,50,170),"8:50"],[F.clock(2,15,170),"2:15, quarter past two"])+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:2,unit:"in",item:4.5,itemLabel:"pencil"}))+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:chartHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{chartOn[x.dataset.n]=!chartOn[x.dataset.n];r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{blkDo(x.dataset.b);r()})},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:tpsNlHtml,bind:tpsNlBind},coins:{name:"Coin values",std:["2.MD.C.8"],html:tpsCoinHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"chart",std:["2.NBT.A.2"],msg:"The 120 chart shows the counting sequence, so counting and skip-counting done with it is supported, not independent."},{t:"chart",std:["2.OA.A.1"],msg:"With the 120 chart the student can count on or back square by square. Note it if the answer came from counting by ones."},{t:"pv",std:["2.NBT.B.7"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so count those items as supported, not independent."},{t:"blocks",std:["2.NBT.B.7"],msg:"If you built the numbers with blocks for the student, the item shows they can trade with a model, not that they can use a written method on their own."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"chart",std:["2.OA.C.3"],msg:"Marking every second square on the 120 chart shows the even numbers for the student. Note that the odd and even answer was supported."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens, and ones, which is what this item asks the student to do. Count it as supported, not independent."},{t:"blocks",std:["2.NBT.A.1","2.NBT.A.3"],msg:"If you built 406 on the mat for the student, the item shows they can read a model, not that they can read the number on their own."},{t:"blocks",std:["2.OA.C.3","2.OA.C.4"],msg:"Pairing or arranging the ones blocks into rows does the grouping for the student. Note it."},{t:"scribe",std:["W.2.1","W.2.2"],msg:"If an adult wrote the words for the student, note it. The writing checks still count, but the printing does not."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
